//! Test plugin for polyplug integration tests.
//!
//! This is a hand-written test plugin (not generated by polyplugc).
//! It implements the "test.add" contract: add(a: u32, b: u32) -> u32.

use polyplug_abi::*;

// ─── FNV-1a hash (compile-time constant for "test.add@1") ────────────────────
// Computed: fnv1a_64(b"test.add@1") = 0xCC4232FAB0410D2B
const TEST_ADD_CONTRACT_ID: u64 = 0xCC4232FAB0410D2B;

// ─── test.add contract types ─────────────────────────────────────────────────

/// Arguments to the `add` function.
#[repr(C)]
pub struct AddArgs {
    pub a: u32,
    pub b: u32,
}

// ─── Implementation ───────────────────────────────────────────────────────────

/// The `add` function: returns a.wrapping_add(b).
///
/// Signature matches the generic dispatch: `extern "C" fn(*const (), *mut ()) -> AbiError`.
///
/// # Safety
/// `args` must point to a valid `AddArgs`. `out` must point to a valid `u32`.
extern "C" fn plugin_add(args: *const (), out: *mut ()) -> AbiError {
    // SAFETY: The host runtime guarantees args points to a valid AddArgs
    // and out points to a valid u32. Enforced by the generated caller code.
    let result: u32 = unsafe {
        let add_args: &AddArgs = &*(args as *const AddArgs);
        add_args.a.wrapping_add(add_args.b)
    };
    // SAFETY: out points to a valid u32 as guaranteed by the host caller.
    unsafe {
        core::ptr::write(out as *mut u32, result);
    }
    abi_error_ok()
}

// ─── Instance lifecycle (stub for test plugin) ────────────────────────────────

/// Stub create_instance for test plugin - returns null instance.
///
/// # Safety
/// Test plugins don't need real instances; dispatch uses global state.
unsafe extern "C" fn create_instance_stub(
    _rt_ctx: *mut core::ffi::c_void,
    _args: *const (),
) -> GuestContractInstance {
    GuestContractInstance::null()
}

/// Stub destroy_instance for test plugin - no cleanup needed.
///
/// # Safety
/// Test plugins don't own instance data.
unsafe extern "C" fn destroy_instance_stub(
    _rt_ctx: *mut core::ffi::c_void,
    _instance: GuestContractInstance,
) {
}

// ─── Static VTable ────────────────────────────────────────────────────────────

/// Wrapper for a function pointer stored in a static vtable array.
/// The pointer is 'static (lifetime of the plugin binary) and read-only.
#[repr(transparent)]
pub struct FnPtr(pub *const ());

// SAFETY: FnPtr wraps a 'static function pointer. Function pointers are safe
// to share across threads — the function itself handles its own synchronization.
unsafe impl Send for FnPtr {}
// SAFETY: Function pointers are inherently Sync — multiple threads may call the
// same function concurrently. The underlying data is read-only 'static memory.
unsafe impl Sync for FnPtr {}

// The function pointer array for the test.add vtable.
// function_id 0 = add(args: AddArgs) -> u32
static TEST_ADD_FNS: [FnPtr; 1] = [FnPtr(plugin_add as *const ())];

static TEST_ADD_INTERFACE: GuestContractInterface = GuestContractInterface {
    contract_id: GuestContractId::from_u64(TEST_ADD_CONTRACT_ID),
    contract_version: Version { major: 1, minor: 0, patch: 0 },
    dispatch_type: DispatchType::Native,
    create_instance: create_instance_stub,
    destroy_instance: destroy_instance_stub,
    dispatch: DispatchMechanisms {
        native: NativeDispatch {
            functions: TEST_ADD_FNS.as_ptr() as *const *const (),
        },
    },
};

static TEST_ADD_DESCRIPTOR: PluginDescriptor = PluginDescriptor {
    name: StringView {
        ptr: b"test_adder".as_ptr(),
        len: 10,
    },
    contract_name: StringView {
        ptr: b"test.add".as_ptr(),
        len: 8,
    },
    version: Version { major: 1, minor: 0, patch: 0 },
};

// ─── ABI Exports ─────────────────────────────────────────────────────────────

/// ABI version sentinel — loader checks this before calling polyplug_init.
#[unsafe(no_mangle)]
pub extern "C" fn polyplug_abi_version() -> u32 {
    1
}

/// Plugin init — called by the loader to register vtables.
///
/// # Safety
/// `rt_ctx` must be a valid opaque pointer to the host runtime context.
/// `host_vtable` must be a valid non-null pointer to a HostVTable from the host.
/// `ctx` must be a valid non-null pointer to a PluginContext from the host.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn polyplug_init(
    rt_ctx: *mut core::ffi::c_void,
    host_vtable: *const HostVTable,
    ctx: *const PluginContext,
) -> AbiError {
    if host_vtable.is_null() {
        return AbiError {
            code: AbiErrorCode::Generic,
            message: string_view_null(),
        };
    }
    if ctx.is_null() {
        return AbiError {
            code: AbiErrorCode::Generic,
            message: string_view_null(),
        };
    }

    // SAFETY: ctx is non-null, checked above.
    let sv: StringView = unsafe { (*ctx).bundle_path };
    LAST_BUNDLE_PATH_PTR.store(sv.ptr as *mut u8, Ordering::SeqCst);
    LAST_BUNDLE_PATH_LEN.store(sv.len, Ordering::SeqCst);

    // SAFETY: host_vtable is non-null and provided by the host runtime per ABI contract.
    let host: &HostVTable = unsafe { &*host_vtable };

    // SAFETY: register_contract is a valid function pointer set by the host.
    // TEST_ADD_DESCRIPTOR and TEST_ADD_INTERFACE are 'static.
    unsafe {
        (host.register_contract)(
            rt_ctx,
            &TEST_ADD_DESCRIPTOR as *const PluginDescriptor,
            &TEST_ADD_INTERFACE as *const GuestContractInterface,
        )
    }
}

use core::sync::atomic::{AtomicPtr, AtomicUsize, Ordering};

static LAST_BUNDLE_PATH_PTR: AtomicPtr<u8> = AtomicPtr::new(core::ptr::null_mut());
static LAST_BUNDLE_PATH_LEN: AtomicUsize = AtomicUsize::new(0);

/// Returns the bundle path passed to the last `polyplug_init` call.
///
/// # Safety
/// The returned StringView is valid as long as the bundle path memory is live.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn polyplug_get_last_bundle_path() -> StringView {
    StringView {
        ptr: LAST_BUNDLE_PATH_PTR.load(Ordering::SeqCst),
        len: LAST_BUNDLE_PATH_LEN.load(Ordering::SeqCst),
    }
}

// ─── Panic test ───────────────────────────────────────────────────────────────

/// A function that always panics — used to verify panic isolation.
///
/// This function is NOT registered in the vtable. The panic test calls it
/// directly via `dlsym` to test the panic behavior.
///
/// # Safety
/// `_args` and `_out` are ignored but must follow standard ABI conventions.
#[unsafe(no_mangle)]
pub extern "C" fn polyplug_panicking_fn(_args: *const (), _out: *mut ()) -> AbiError {
    panic!("intentional test panic");
}